mapper.insert:
INSERT INTO user_novel_progress (novel_id, user_id, chapter_id, read_at)
SELECT n.id, n.user_id, c.id, NOW()
FROM user_novel n
JOIN user_novel_chapter c ON c.novel_id = n.id AND c.id = #{chapterId}
WHERE n.id = #{novelId} AND n.user_id = #{userId}
ON DUPLICATE KEY UPDATE chapter_id = #{chapterId}, read_at = NOW()

